class ConversationalEntity:
    def __init__(self, conversation_id):
        self.conversation_id = conversation_id
        self.context = {}

    def add_context(self, key, value):
        self.context[key] = value

    def get_context(self, key):
        return self.context.get(key, None)

    def clear_context(self):
        self.context = {}

class SwitchConversationRequest:
    def __init__(self):
        self.new_conversation_id = None

    def set_new_conversation_id(self, conversation_id):
        self.new_conversation_id = conversation_id

    def get_new_conversation_id(self):
        return self.new_conversation_id

    def should_switch(self):
        return self.new_conversation_id is not None

class SwitchConversationHandler:
    def __init__(self, current_conversation, request: SwitchConversationRequest):
        self.current_conversation = current_conversation
        self.request = request

    def handle_request(self):
        if self.request.should_switch():
            # Clear the old conversation context
            self.current_conversation.clear_context()
            # Create a new conversation entity
            new_conversation = ConversationalEntity(self.request.get_new_conversation_id())
            return new_conversation
        else:
            return self.current_conversation

# Example usage
current_conversation = ConversationalEntity("conversation1")
request = SwitchConversationRequest()
request.set_new_conversation_id("conversation2")

handler = SwitchConversationHandler(current_conversation, request)
new_conversation = handler.handle_request()

print(f"Old conversation context: {current_conversation.context}")
print(f"New conversation: {new_conversation.conversation_id}")
```

